// ReturnShield - Record Feedback (spec sections 16 + 19)
// Doubles as: (a) the closed-loop feedback store ("did this recommendation
// work?"), and (b) the human-approval record for recommendations the
// Self-Verification Engine flagged with requires_human_approval = true.

const body = $input.first().json.body !== undefined ? $input.first().json.body : $input.first().json;

const VALID_OUTCOMES = ['accepted', 'rejected', 'implemented', 'resolved', 'ineffective', 'incorrect', 'approved', 'denied'];

const run_id = body && typeof body.run_id === 'string' ? body.run_id.trim() : '';
const target = body && typeof body.target === 'string' ? body.target.trim() : '';
const outcome = body && typeof body.outcome === 'string' ? body.outcome.trim().toLowerCase() : '';
const note = body && typeof body.note === 'string' ? body.note.trim() : '';
const recorded_by = body && typeof body.recorded_by === 'string' ? body.recorded_by.trim() : 'unspecified';

const errors = [];
if (!run_id) errors.push('Missing "run_id" (string) - which analysis run this feedback is about.');
if (!target) errors.push('Missing "target" (string) - which recommendation/problem this refers to, e.g. "courier: Xpress Logistics".');
if (!outcome) errors.push('Missing "outcome" (string).');
else if (!VALID_OUTCOMES.includes(outcome)) errors.push('"outcome" must be one of: ' + VALID_OUTCOMES.join(', ') + '.');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    run_id, target, outcome, note, recorded_by,
    recorded_at: new Date().toISOString()
  }
}];

const j = $json;
return [{
  json: {
    product: 'ReturnShield AI',
    error: true,
    messages: j.errors,
    expected_format: {
      run_id: 'string (required)',
      target: 'string (required) - e.g. "courier: Xpress Logistics"',
      outcome: 'one of: accepted, rejected, implemented, resolved, ineffective, incorrect, approved, denied',
      note: 'string (optional)',
      recorded_by: 'string (optional) - who is recording this outcome'
    },
    generated_at: new Date().toISOString()
  }
}];

const j = $json;
return [{
  json: {
    product: 'ReturnShield AI',
    stored: true,
    run_id: j.run_id,
    target: j.target,
    outcome: j.outcome,
    recorded_at: j.recorded_at,
    note: 'Feedback recorded. Future analysis runs referencing this run_id can factor this outcome in (spec section 19 closed-loop learning).'
  }
}];
